def calculate_final_grade(grade1, grade2, grade3):
    grades = [grade1, grade2, grade3]
    total = 0
    for grade in grades:
        if not is_incomplete(grade):
            total += grade
    return total

def is_incomplete(grade):
    return 20 <= grade <= 29

